// ignore_for_file: unused_element, unnecessary_cast


class JobPlacement {
  /// The name of the cluster where the job will be submitted
  final String clusterName;
  /// Output-only. A cluster UUID generated by the Cloud Dataproc service when the job is submitted
  final String? clusterUuid;

  /// Creates a new [JobPlacement].
  /// [clusterName] The name of the cluster where the job will be submitted
  /// [clusterUuid] Output-only. A cluster UUID generated by the Cloud Dataproc service when the job is submitted
  JobPlacement({
    required this.clusterName,
    this.clusterUuid,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'clusterName': clusterName,
      'clusterUuid': ?clusterUuid,
    };
  }

  factory JobPlacement.fromMap(Map<String, dynamic> map) {
    return JobPlacement(
      clusterName: map['clusterName'] as String,
      clusterUuid: map['clusterUuid'] == null ? null : map['clusterUuid'] as String,
    );
  }
}

